local CushionMaker = {}
local PRODUCTS = {
    straw_pillow = { name = "Slamnata blazina", strawCost = 1, linenCost = 1, time = 1, cost = 8, comfort = 4, description = "Preprosta slamnata blazina za kmete." },
    wool_cushion = { name = "Volnena blazina", woolCost = 1, linenCost = 1, time = 2, cost = 22, comfort = 7, prestige = 1, description = "Volnena blazina z laneno prevleko." },
    feather_cushion = { name = "Peresna blazina", featherCost = 1, silkCost = 1, time = 3, cost = 65, comfort = 12, prestige = 3, description = "Peresna blazina v svileni prevleki." },
    embroidered_cushion = { name = "Vezena blazina", silkCost = 1, featherCost = 1, threadCost = 1, time = 5, cost = 160, comfort = 14, prestige = 6, happiness = 1, description = "Vezena blazina za plemiče." },
    gold_thread_cushion = { name = "Zlato nitna blazina", silkCost = 2, goldCost = 1, featherCost = 1, time = 7, cost = 380, comfort = 16, prestige = 12, happiness = 2, description = "Blazina z zlatimi nitmi." },
    royal_throne_cushion = { name = "Kraljevska prestolna blazina", silkCost = 3, goldCost = 2, silverCost = 1, featherCost = 2, jewelCost = 1, time = 11, cost = 950, comfort = 22, prestige = 30, happiness = 6, description = "Veliki kraljevski prestolni blazina z dragulji." },
}
local BUILDINGS = {
    workshop = { name = "Blazinarska delavnica", cost = { gold = 220, wood = 100 }, upkeep = 5, qualityBonus = 5 },
    sewing_room = { name = "Šivalnica", cost = { gold = 700, wood = 200, stone = 180, silk = 6 }, upkeep = 17, qualityBonus = 18 },
    embroidery_room = { name = "Vezenilnica", cost = { gold = 1600, wood = 280, stone = 350, silver = 25, thread = 8 }, upkeep = 38, qualityBonus = 30 },
    royal_cushion_atelier = { name = "Kraljevski atelje blazin", cost = { gold = 5500, wood = 500, stone = 700, gold = 50, silk = 18 }, upkeep = 100, qualityBonus = 55, prestigeBonus = 28 },
}
CushionMaker.strawStock = 14; CushionMaker.linenStock = 12; CushionMaker.woolStock = 12; CushionMaker.featherStock = 10; CushionMaker.silkStock = 8; CushionMaker.threadStock = 8; CushionMaker.goldStock = 6; CushionMaker.silverStock = 6; CushionMaker.jewelStock = 4
CushionMaker.productStock = {}; CushionMaker.buildings = {}; CushionMaker.maker = nil; CushionMaker.activeMaking = {}; CushionMaker.totalProducts = 0; CushionMaker.dayTimer = 0
function CushionMaker.init() CushionMaker.strawStock=14; CushionMaker.linenStock=12; CushionMaker.woolStock=12; CushionMaker.featherStock=10; CushionMaker.silkStock=8; CushionMaker.threadStock=8; CushionMaker.goldStock=6; CushionMaker.silverStock=6; CushionMaker.jewelStock=4; CushionMaker.productStock={}; CushionMaker.buildings={}; CushionMaker.maker=nil; CushionMaker.activeMaking={}; CushionMaker.totalProducts=0; CushionMaker.dayTimer=0; print("[CushionMaker] Royal Cushion Maker System initialized (6 products, 4 buildings)") end
function CushionMaker.hireMaker(n,s) s=s or math.random(50,90); local c=430+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CushionMaker.maker={name=n or ("Blazinar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Blazinar najet: %s (spretnost: %d)",CushionMaker.maker.name,s),"success") end; return true end
function CushionMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CushionMaker.build(id) local ok,e=CushionMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CushionMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CushionMaker.getQualityBonus() local b=0; for _,bd in ipairs(CushionMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CushionMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.strawCost and CushionMaker.strawStock<(d.strawCost or 0) then return false,"Premalo slame" end; if d.linenCost and CushionMaker.linenStock<(d.linenCost or 0) then return false,"Premalo lana" end; if d.woolCost and CushionMaker.woolStock<(d.woolCost or 0) then return false,"Premalo volne" end; if d.featherCost and CushionMaker.featherStock<(d.featherCost or 0) then return false,"Premalo peres" end; if d.silkCost and CushionMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.threadCost and CushionMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.goldCost and CushionMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.silverCost and CushionMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.jewelCost and CushionMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #CushionMaker.buildings==0 then return false,"Potrebna delavnica" end; if not CushionMaker.maker then return false,"Potreben blazinar" end; return true end
function CushionMaker.make(pt,qty) qty=qty or 1; local ok,e=CushionMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.strawCost then CushionMaker.strawStock=CushionMaker.strawStock-d.strawCost*qty end; if d.linenCost then CushionMaker.linenStock=CushionMaker.linenStock-d.linenCost*qty end; if d.woolCost then CushionMaker.woolStock=CushionMaker.woolStock-d.woolCost*qty end; if d.featherCost then CushionMaker.featherStock=CushionMaker.featherStock-d.featherCost*qty end; if d.silkCost then CushionMaker.silkStock=CushionMaker.silkStock-d.silkCost*qty end; if d.threadCost then CushionMaker.threadStock=CushionMaker.threadStock-d.threadCost*qty end; if d.goldCost then CushionMaker.goldStock=CushionMaker.goldStock-d.goldCost*qty end; if d.silverCost then CushionMaker.silverStock=CushionMaker.silverStock-d.silverCost*qty end; if d.jewelCost then CushionMaker.jewelStock=CushionMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if CushionMaker.maker then t=math.max(1,t-math.floor(CushionMaker.maker.skill/12)) end; table.insert(CushionMaker.activeMaking,{id="cushion_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,comfort=d.comfort or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CushionMaker.completeMaking(m) local q=1.0+(CushionMaker.getQualityBonus()/100); if CushionMaker.maker then q=q+(CushionMaker.maker.skill/180) end; q=math.min(2.0,q); CushionMaker.productStock[m.productType]=(CushionMaker.productStock[m.productType] or 0)+m.quantity; CushionMaker.totalProducts=CushionMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CushionMaker.maker then CushionMaker.maker.itemsMade=CushionMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then CushionMaker.maker.skill=math.min(100,CushionMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Blazina izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cushion.completed",{productName=m.productName,prestige=m.prestige}) end end
function CushionMaker.update(dt) if not _G.state then return end; CushionMaker.dayTimer=CushionMaker.dayTimer+dt; if CushionMaker.dayTimer>=30 then CushionMaker.dayTimer=0; for i=#CushionMaker.activeMaking,1,-1 do local m=CushionMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CushionMaker.completeMaking(m); table.remove(CushionMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CushionMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CushionMaker.maker then tu=tu+11 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CushionMaker.getStats() return {strawStock=CushionMaker.strawStock,linenStock=CushionMaker.linenStock,woolStock=CushionMaker.woolStock,featherStock=CushionMaker.featherStock,silkStock=CushionMaker.silkStock,threadStock=CushionMaker.threadStock,goldStock=CushionMaker.goldStock,silverStock=CushionMaker.silverStock,jewelStock=CushionMaker.jewelStock,productStock=CushionMaker.productStock,numBuildings=#CushionMaker.buildings,hasMaker=CushionMaker.maker~=nil,makerName=CushionMaker.maker and CushionMaker.maker.name or "—",makerSkill=CushionMaker.maker and CushionMaker.maker.skill or 0,activeMaking=#CushionMaker.activeMaking,totalProducts=CushionMaker.totalProducts} end
return CushionMaker
